import { Sapphire, SapphireContentScriptPlugin, findMatchingCommand, triggerCommand } from "@x8r/sapphire";
import JSZip from "jszip";

// Helper to normalize extension zip/crx archives (fixes subfolder nesting and crx headers)
async function normalizeExtensionBuffer(buffer: ArrayBuffer, _filename = "extension.crx"): Promise<ArrayBuffer> {
	let rawBuf = buffer;
	const view = new DataView(rawBuf);
	if (rawBuf.byteLength >= 4) {
		const magic = String.fromCharCode(view.getUint8(0), view.getUint8(1), view.getUint8(2), view.getUint8(3));
		if (magic === "Cr24") {
			const version = view.getUint32(4, true);
			let zipStart = 0;
			if (version === 2) {
				const pubKeyLen = view.getUint32(8, true);
				const sigLen = view.getUint32(12, true);
				zipStart = 16 + pubKeyLen + sigLen;
			} else if (version === 3) {
				const headerSize = view.getUint32(8, true);
				zipStart = 12 + headerSize;
			}
			if (zipStart > 0 && zipStart < rawBuf.byteLength) {
				rawBuf = rawBuf.slice(zipStart);
			}
		}
	}

	try {
		const zip = await JSZip.loadAsync(rawBuf);
		// Check if manifest.json exists at root
		if (zip.file("manifest.json")) {
			return rawBuf;
		}

		// Look for manifest.json in any subfolder
		let manifestPath = "";
		zip.forEach((relPath, file) => {
			if (!file.dir && relPath.endsWith("manifest.json") && (!manifestPath || relPath.split("/").length < manifestPath.split("/").length)) {
				manifestPath = relPath;
			}
		});

		if (manifestPath) {
			const prefix = manifestPath.substring(0, manifestPath.lastIndexOf("manifest.json"));
			const newZip = new JSZip();
			const promises: Promise<void>[] = [];
			zip.forEach((relPath, file) => {
				if (file.dir) return;
				if (relPath.startsWith(prefix)) {
					const newRelPath = relPath.substring(prefix.length);
					if (newRelPath) {
						promises.push(
							file.async("arraybuffer").then((ab) => {
								newZip.file(newRelPath, ab);
							})
						);
					}
				}
			});
			await Promise.all(promises);

			return await newZip.generateAsync({ type: "arraybuffer" });
		}
	} catch (e) {
		console.warn("normalizeExtensionBuffer zip inspect error:", e);
	}

	return rawBuf;
}

(globalThis as any).Sapphire = Sapphire;
(globalThis as any).SapphireContentScriptPlugin = SapphireContentScriptPlugin;
(globalThis as any).findMatchingCommand = findMatchingCommand;
(globalThis as any).triggerCommand = triggerCommand;
(globalThis as any).JSZip = JSZip;
(globalThis as any).normalizeExtensionBuffer = normalizeExtensionBuffer;

export { Sapphire, SapphireContentScriptPlugin, findMatchingCommand, triggerCommand, JSZip, normalizeExtensionBuffer };
export default Sapphire;

